import { test, expect } from '@playwright/test';

test.describe('Login Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should not allow submission with empty fields', async ({ page }) => {
    await page.getByRole('button', { name: /login/i }).click();
    const errorMessage = await page.getByText(/please fill out this field/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should show error messages for empty username and password', async ({ page }) => {
    await page.getByLabel('Username').fill('');
    await page.getByLabel('Password').fill('');
    await page.getByRole('button', { name: /login/i }).click();

    const usernameError = await page.getByText(/please fill out this field/i).nth(0);
    const passwordError = await page.getByText(/please fill out this field/i).nth(1);

    await expect(usernameError).toBeVisible();
    await expect(passwordError).toBeVisible();
  });
});
